/*
 * This file includes the functions that are used to interact with the main database.
 * To add a new function, add it in the class MainDB.
 */

class MainDB {
  MainDB._();
  static MainDB? _instance;
  static MainDB get instance => _instance ??= MainDB._();

  Isar? _isar;

  Isar get isar => _isar!;

  Future<bool> initMainDB({Isar? mock}) async {
    if (mock != null) {
      _isar = mock;
      return true;
    }
    if (_isar != null && isar.isOpen) return false;
    _isar = await Isar.open(
      [
        TransactionNoteSchema,
        UTXOSchema,
        AddressSchema,
        AddressLabelSchema,
        TransactionBlockExplorerSchema,
        StackThemeSchema,
        ContactEntrySchema,
        WalletInfoSchema,
        TransactionV2Schema,
        WalletInfoMetaSchema,
      ],
      directory: (await StackFileSystem.applicationIsarDirectory()).path,
      // inspector: kDebugMode,
      inspector: false,
      name: "wallet_data",
      maxSizeMiB: Platform.isWindows ? 1024 : 512,
    );

    return true;
  }

  // contact entries
  List<ContactEntry> getContactEntries() {
    return isar.contactEntrys.where().sortByName().findAllSync();
  }

  Future<bool> deleteContactEntry({required String id}) {
    try {
      return isar.writeTxn(() async {
        await isar.contactEntrys.deleteByCustomId(id);
        return true;
      });
    } catch (e) {
      throw MainDBException("failed deleteContactEntry: $id", e);
    }
  }

  Future<bool> isContactEntryExists({required String id}) async {
    return isar.contactEntrys
        .where()
        .customIdEqualTo(id)
        .count()
        .then((value) => value > 0);
  }

  ContactEntry? getContactEntry({required String id}) {
    return isar.contactEntrys.where().customIdEqualTo(id).findFirstSync();
  }

  Future<bool> putContactEntry({required ContactEntry contactEntry}) async {
    try {
      return await isar.writeTxn(() async {
        await isar.contactEntrys.put(contactEntry);
        return true;
      });
    } catch (e) {
      throw MainDBException("failed putContactEntry: $contactEntry", e);
    }
  }

  // tx block explorers
  TransactionBlockExplorer? getTransactionBlockExplorer({
    required CryptoCurrency cryptoCurrency,
  }) {
    return isar.transactionBlockExplorers
        .where()
        .tickerEqualTo(cryptoCurrency.ticker)
        .findFirstSync();
  }

  Future<int> putTransactionBlockExplorer(
    TransactionBlockExplorer explorer,
  ) async {
    try {
      return await isar.writeTxn(() async {
        return await isar.transactionBlockExplorers.put(explorer);
      });
    } catch (e) {
      throw MainDBException("failed putTransactionBlockExplorer: $explorer", e);
    }
  }

  // addresses
  QueryBuilder<Address, Address, QAfterWhereClause> getAddresses(
    String walletId,
  ) => isar.addresses.where().walletIdEqualTo(walletId);

  Future<List<int>> updateOrPutAddresses(List<Address> addresses) async {
    if (addresses.isEmpty) return [];
    try {
      final List<int> ids = [];
      await isar.writeTxn(() async {
        for (final address in addresses) {
          final storedAddress = await isar.addresses.getByValueWalletId(
            address.value,
            address.walletId,
          );

          int id;
          if (storedAddress == null) {
            id = await isar.addresses.put(address);
          } else {
            address.id = storedAddress.id;
            id = await isar.addresses.put(address);
          }
          ids.add(id);
        }
      });
      return ids;
    } catch (e) {
      throw MainDBException("failed updateOrPutAddresses: $addresses", e);
    }
  }

  Future<Address?> getAddress(String walletId, String address) async {
    return isar.addresses.getByValueWalletId(address, walletId);
  }

  // transactions

  // utxos
  QueryBuilder<UTXO, UTXO, QAfterWhereClause> getUTXOs(String walletId) =>
      isar.utxos.where().walletIdEqualTo(walletId);

  Future<void> putUTXO(UTXO utxo) => isar.writeTxn(() async {
    await isar.utxos.put(utxo);
  });

  Future<void> putUTXOs(List<UTXO> utxos) => utxos.isEmpty
      ? Future.value()
      : isar.writeTxn(() async {
          await isar.utxos.putAll(utxos);
        });

  /// Make [utxos] the wallet's coins: coins no longer listed are removed,
  /// new ones added, and stored ones keep the user's flags (see below).
  /// Returns whether any coin is new.
  ///
  /// Runs on every sync with all of the wallet's coins, so the stored ones
  /// are read in one query and only rows that changed are written: one
  /// query per coin and rewriting them all took seconds on slow phones
  /// for a wallet with a few hundred coins.
  Future<bool> updateUTXOs(String walletId, List<UTXO> utxos) async {
    bool newUTXO = false;

    await isar.writeTxn(() async {
      final stored = {
        for (final u in await getUTXOs(walletId).findAll()) (u.txid, u.vout): u,
      };
      // By outpoint: a coin listed twice is kept once.
      final rows = <(String, int), UTXO>{};
      for (final utxo in utxos) {
        final storedUtxo = stored[(utxo.txid, utxo.vout)];
        if (storedUtxo != null) {
          // Preserve user-set flags, but allow a fresh auto-freeze (e.g.
          // masternode collateral detected after registration) unless the
          // user deliberately unfroze this utxo before. Never auto-unfreeze:
          // a flaky network check must not unlock coins.
          final applyAutoBlock =
              utxo.isBlocked &&
              !storedUtxo.isBlocked &&
              !storedUtxo.userUnfroze;
          rows[(utxo.txid, utxo.vout)] = storedUtxo.copyWith(
            value: utxo.value,
            address: utxo.address,
            blockTime: utxo.blockTime,
            blockHeight: utxo.blockHeight,
            blockHash: utxo.blockHash,
            // passing null keeps the stored value
            otherData: utxo.otherData,
            isBlocked: applyAutoBlock ? true : null,
            blockedReason: applyAutoBlock ? utxo.blockedReason : null,
            name: applyAutoBlock && storedUtxo.name.isEmpty ? utxo.name : null,
          );
        } else {
          newUTXO = true;
          rows[(utxo.txid, utxo.vout)] = utxo;
        }
      }

      final gone = [
        for (final e in stored.entries)
          if (!rows.containsKey(e.key)) e.value.id,
      ];
      final changed = [
        for (final e in rows.entries)
          if (!_sameUtxo(stored[e.key], e.value)) e.value,
      ];
      if (gone.isNotEmpty) await isar.utxos.deleteAll(gone);
      if (changed.isNotEmpty) await isar.utxos.putAll(changed);
    });

    return newUTXO;
  }

  static bool _sameUtxo(UTXO? a, UTXO b) =>
      a != null &&
      a.id == b.id &&
      a.value == b.value &&
      a.name == b.name &&
      a.isBlocked == b.isBlocked &&
      a.blockedReason == b.blockedReason &&
      a.isCoinbase == b.isCoinbase &&
      a.blockHash == b.blockHash &&
      a.blockHeight == b.blockHeight &&
      a.blockTime == b.blockTime &&
      a.address == b.address &&
      a.used == b.used &&
      a.otherData == b.otherData;

  Stream<UTXO?> watchUTXO({required Id id, bool fireImmediately = false}) {
    return isar.utxos.watchObject(id, fireImmediately: fireImmediately);
  }

  // transaction notes
  QueryBuilder<TransactionNote, TransactionNote, QAfterWhereClause>
